#include <utility>
#include <iostream>
#include <functional>

int main() {
    int x = 100;
    // Convenience: Deduce std::pair<int, double>
    auto p1 = std::make_pair(42, 3.14);

    // Pitfall: x is passed by value (decay)
    auto p2 = std::make_pair(x, 'A');
    x = 200;
    // p2.first remains 100

    // Correct reference handling using std::ref
    auto p3 = std::make_pair(std::ref(x), 1);
    // p3.first refers to the updated x (200)
}
